import{_t as e,it as t,n,rt as r}from"./chunks/framework.C5Z6qjff.js";var i=JSON.parse(`{"title":"Betrieb","description":"","frontmatter":{"title":"Betrieb","covers":{"screens":[],"stories":["US-011","US-019"]}},"headers":[],"relativePath":"de/administration/operations.md","filePath":"de/administration/operations.md"}`),a={name:`de/administration/operations.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="betrieb" tabindex="-1">Betrieb <a class="header-anchor" href="#betrieb" aria-label="Permalink to “Betrieb”">​</a></h1><h2 id="datenbankrollen" tabindex="-1">Datenbankrollen <a class="header-anchor" href="#datenbankrollen" aria-label="Permalink to “Datenbankrollen”">​</a></h2><table tabindex="0"><thead><tr><th>Rolle</th><th>Verwendet von</th><th>Besitzt</th></tr></thead><tbody><tr><td><code>oea_owner</code></td><td>Migrationsschritt: <code>db/migration</code>, <code>db/migration-audit</code></td><td>Schemas <code>public</code>, <code>audit</code> und ihre Objekte</td></tr><tr><td><code>oea_reporting_owner</code></td><td>Migrationsschritt: <code>db/migration-reporting</code></td><td>Schemas <code>reporting</code>, <code>reporting_ctx</code> und ihre Objekte</td></tr><tr><td><code>oea_app</code></td><td>Backend zur Laufzeit</td><td>nichts</td></tr><tr><td><code>oea_audit_cleanup</code></td><td>Job für die Audit-Aufbewahrung</td><td>nichts</td></tr><tr><td><code>oea_auditor</code></td><td>Audit-Prüfung, externe Prüfer</td><td>nichts</td></tr><tr><td><code>oea_analytics</code></td><td>direkte Analytics-Verbindungen</td><td>nichts</td></tr></tbody></table><p>Keine Rolle ist <code>SUPERUSER</code>, <code>CREATEROLE</code>, <code>CREATEDB</code> oder <code>BYPASSRLS</code>, und keine OEA-Rolle ist Mitglied einer anderen OEA-Rolle. Die Laufzeitrolle <code>oea_app</code> hat auf den Audit-Tabellen nur <code>INSERT</code> und <code>SELECT</code>; andernfalls startet das Backend nicht. Rollenpasswörter rotierst du, indem du das Provisioning-Skript erneut ausführst (siehe <a href="./../setup/installation#provisioning-einmalig">Installation</a>).</p><h2 id="request-size-limits" tabindex="-1">Größenlimits für Requests <a class="header-anchor" href="#request-size-limits" aria-label="Permalink to “Größenlimits für Requests”">​</a></h2><p>Request-Bodys werden begrenzt, bevor sie verarbeitet werden. Ein größerer Body wird mit <code>413</code> und dem Problem-Typ <code>urn:oea:problem:request-too-large</code> beantwortet (<code>package-too-large</code> bei Metamodell-Paketen):</p><table tabindex="0"><thead><tr><th>Einstellung</th><th>Standard</th><th>Gilt für</th></tr></thead><tbody><tr><td><code>oea.web.request-size.default</code> (<code>OEA_WEB_REQUESTSIZE_DEFAULT</code>)</td><td><code>1MB</code></td><td>jede Operation mit Request-Body</td></tr><tr><td><code>oea.web.request-size.entity-batch</code> (<code>OEA_WEB_REQUESTSIZE_ENTITYBATCH</code>)</td><td><code>10MB</code></td><td><code>POST /entities/batch</code></td></tr><tr><td><code>oea.metamodel.import.max-size</code> (<code>OEA_METAMODEL_IMPORT_MAXSIZE</code>)</td><td><code>10MB</code></td><td><code>POST /admin/metamodel/import</code></td></tr></tbody></table><p>Ein Reverse Proxy vor OEA sollte mindestens den größten dieser Werte zulassen.</p><h2 id="rate-limits" tabindex="-1">Rate Limits <a class="header-anchor" href="#rate-limits" aria-label="Permalink to “Rate Limits”">​</a></h2><p>Jede angemeldete Person und jedes Systemadministrator-Konto darf pro Minute eine begrenzte Zahl von Requests senden. Die Minute beginnt mit dem ersten Request; ein Request über dem Limit wird mit <code>429</code>, dem Problem-Typ <code>urn:oea:problem:too-many-requests</code> und dem Header <code>Retry-After</code> beantwortet, der die Sekunden bis zum nächsten angenommenen Request nennt. Von einem abgewiesenen Request wird nichts verarbeitet, und andere Benutzer sind nicht betroffen.</p><table tabindex="0"><thead><tr><th>Einstellung</th><th>Standard</th><th>Gilt für</th></tr></thead><tbody><tr><td><code>oea.web.rate-limit.requests-per-minute</code> (<code>OEA_WEB_RATELIMIT_REQUESTSPERMINUTE</code>)</td><td><code>600</code></td><td>jeden Request eines angemeldeten Principals</td></tr><tr><td><code>oea.web.rate-limit.entity-batch-per-minute</code> (<code>OEA_WEB_RATELIMIT_ENTITYBATCHPERMINUTE</code>)</td><td><code>10</code></td><td><code>POST /entities/batch</code>, zusätzlich zum Request-Limit</td></tr></tbody></table><p>Beide Werte müssen mindestens <code>1</code> sein, sonst startet das Backend nicht. Die erste Abweisung eines Principals innerhalb einer Minute wird im Audit-Trail als <code>auth.throttled</code> mit dem Scope <code>principal</code> festgehalten.</p><p>Die Zähler liegen im Speicher des Backends. Betreibst du mehrere Backend-Instanzen hinter einem Load Balancer, zählt jede Instanz für sich, sodass ein Principal bis zum Limit mal der Zahl der Instanzen senden kann. Nach einem Neustart beginnt die Zählung von vorn.</p><p>Logins und die Setup-Seite werden getrennt davon pro Login-Name und Absenderadresse gedrosselt (100 Fehlversuche innerhalb von 10 Minuten). Ein Reverse Proxy mit eigenem Rate Limiting ist eine sinnvolle zusätzliche Schicht, wenn die Instanz aus dem Internet erreichbar ist; er ersetzt diese Limits nicht.</p><h2 id="key-encryption-key" tabindex="-1">Key-Encryption-Key <a class="header-anchor" href="#key-encryption-key" aria-label="Permalink to “Key-Encryption-Key”">​</a></h2><p>Gespeicherte Geheimnisse – TOTP-Secrets und Client-Secrets von Identity-Providern – werden mit AES-256-GCM unter dem Key-Encryption-Key verschlüsselt, einer Datei außerhalb der Datenbank. Jeder verschlüsselte Wert speichert die ID seines Schlüssels (die ersten 16 Hex-Ziffern des SHA-256 des Schlüssels).</p><ul><li><code>oea.security.kek.current</code> (<code>OEA_SECURITY_KEK_CURRENT</code>) nennt die Schlüsseldatei; das Compose-Setup bindet die mit <code>OEA_KEK_FILE</code> genannte Datei als Secret <code>/run/secrets/oea_kek</code> ein.</li><li>Halte den Schlüssel aus Datenbank-Backups heraus und bewahre ihn getrennt auf. Ein Datenbank-Dump ohne den Schlüssel gibt die Geheimnisse nicht preis – und ohne den Schlüssel sind die Geheimnisse verloren.</li></ul><h3 id="schlussel-rotieren" tabindex="-1">Schlüssel rotieren <a class="header-anchor" href="#schlussel-rotieren" aria-label="Permalink to “Schlüssel rotieren”">​</a></h3><ol><li><p>Erzeuge eine neue Schlüsseldatei und konfiguriere sie als <code>oea.security.kek.current</code>; konfiguriere die alte als <code>oea.security.kek.previous</code> (eine Liste von Dateien, <code>OEA_SECURITY_KEK_PREVIOUS</code>).</p></li><li><p>Verschlüssle alle gespeicherten Geheimnisse mit den Laufzeit-Zugangsdaten neu:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oea-backend.jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secrets</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reencrypt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --spring.datasource.url=jdbc:postgresql://db.example.org:5432/oea</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --spring.datasource.username=oea_app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --spring.datasource.password=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA_APP_PASSWORD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --oea.security.kek.current=/run/secrets/oea_kek</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --oea.security.kek.previous=/run/secrets/oea_kek_previous</span></span></code></pre></div></li><li><p>Entferne den alten Schlüssel aus der Konfiguration und vernichte ihn.</p></li></ol><p>Der Befehl verschlüsselt in einer Transaktion neu und gibt <code>OK &lt;n&gt; secret(s) re-encrypted with key &lt;key ID&gt;</code> aus. Exit-Codes: <code>0</code> erledigt, <code>1</code> ein Wert konnte mit den konfigurierten Schlüsseln nicht entschlüsselt werden (nichts wurde geändert), <code>2</code> Aufruf- oder Verbindungsfehler.</p><h2 id="log-format" tabindex="-1">Log-Format <a class="header-anchor" href="#log-format" aria-label="Permalink to “Log-Format”">​</a></h2><p>Das Backend und seine Befehle loggen als Klartext auf die Konsole. Für eine Log-Plattform oder ein SIEM stellst du auf JSON-Zeilen in einem der Formate <code>ecs</code> (Elastic Common Schema), <code>logstash</code> oder <code>gelf</code> (Graylog) um:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># .env der Compose-Installation</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OEA_LOG_FORMAT</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ecs</span></span></code></pre></div><p>Ohne Compose setzt du die Umgebungsvariable <code>LOGGING_STRUCTURED_FORMAT_CONSOLE</code> (oder die Option <code>--logging.structured.format.console=ecs</code>). Ein leerer Wert lässt den Klartext.</p><ul><li>Jede JSON-Zeile enthält Zeitstempel, Level, Logger und Nachricht. Ein Eintrag, der während eines HTTP-Requests geschrieben wird, hat zusätzlich das Feld <code>requestId</code> – denselben Wert wie der Header <code>X-Request-Id</code> und die Request-ID des Audit-Eintrags.</li><li>Kein Eintrag enthält Passwörter, Setup-Tokens, Geheimnisse zweiter Faktoren oder Sitzungs-Tokens, in keinem Format.</li><li>Checkpoint-Einträge behalten ihre Nachricht und bekommen die Felder <code>event</code>, <code>chainSeq</code>, <code>recordHash</code> und <code>at</code>. GELF stellt ihnen <code>_</code> voran. <code>audit verify --checkpoints</code> liest Checkpoints aus Klartext- und JSON-Zeilen, auch gemischt in einer Datei (siehe unten).</li></ul><h2 id="password-login-of-persons" tabindex="-1">Passwort-Login von Personen <a class="header-anchor" href="#password-login-of-persons" aria-label="Permalink to “Passwort-Login von Personen”">​</a></h2><p>Personen melden sich über deinen Identity-Provider an. Auf einer Instanz ohne Identity-Provider kannst du Personen stattdessen mit ihrer E-Mail-Adresse und einem Passwort anmelden lassen. Das ist auf einer neuen Instanz aus; du schaltest es ausdrücklich ein:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Umgebung des Backends (oder --oea.auth.person-password.enabled=true)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OEA_AUTH_PERSONPASSWORD_ENABLED</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># optional: wie lange ein Initialpasswort gilt (1 Stunde bis 30 Tage, Standard 72 Stunden)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OEA_AUTH_PERSONPASSWORD_TEMPORARYPASSWORDVALIDITY</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">PT72H</span></span></code></pre></div><ul><li>Eine Administratorin oder ein Administrator setzt dann pro Person ein Initialpasswort (siehe <a href="./identity-providers#set-an-initial-password">Identity-Provider und Personen</a>); die Person ändert es bei der ersten Anmeldung.</li><li>Wer sich mit einem Passwort anmeldet, hat noch keinen zweiten Faktor; Rollen mit administrativen Berechtigungen gelten dann nicht. Behalte für die Administration das lokale Systemadmin-Konto, bis zweite Faktoren für Personen verfügbar sind.</li><li>Solange die Einstellung aus ist, scheitert der Passwort-Login einer Person wie ein falsches Passwort, und das Setzen eines Initialpassworts wird mit <code>409</code> abgelehnt.</li></ul><h2 id="verify-the-audit-trail" tabindex="-1">Audit-Trail prüfen <a class="header-anchor" href="#verify-the-audit-trail" aria-label="Permalink to “Audit-Trail prüfen”">​</a></h2><p>Jeder Audit-Eintrag ist ein Glied einer Hash-Kette, die die Datenbank berechnet. Der Prüfbefehl berechnet die Kette mit der nur lesenden Rolle <code>oea_auditor</code> neu:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oea-backend.jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> audit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --oea.audit-verify.url=jdbc:postgresql://db.example.org:5432/oea</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --oea.audit-verify.password=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA_AUDITOR_PASSWORD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --checkpoints=/var/log/oea/backend.log</span></span></code></pre></div><p>Mit Compose: <code>docker compose run --rm migrate audit verify --oea.audit-verify.url=jdbc:postgresql://postgres:5432/oea --oea.audit-verify.password=…</code>. Die Umgebungsvariablen <code>OEA_AUDITVERIFY_URL</code> und <code>OEA_AUDITVERIFY_PASSWORD</code> funktionieren ebenfalls.</p><table tabindex="0"><thead><tr><th>Exit-Code</th><th>Bedeutung</th></tr></thead><tbody><tr><td><code>0</code></td><td>Kette intakt (<code>OK &lt;links&gt; links, head &lt;chain_seq&gt; &lt;hash&gt;</code>)</td></tr><tr><td><code>1</code></td><td>erstes gebrochenes Glied, fehlendes Glied oder ein Datenbank-Head, der hinter einem Checkpoint liegt oder von ihm abweicht (<code>BROKEN …</code>)</td></tr><tr><td><code>2</code></td><td>Aufruf- oder Verbindungsfehler</td></tr></tbody></table><p><strong>Checkpoints</strong>: Das Backend hängt alle 60 Minuten (<code>oea.audit.checkpoint-interval</code>, 5–1440 Minuten) und beim geordneten Herunterfahren einen Checkpoint an und schreibt eine Logzeile <code>event=audit.checkpoint chainSeq=… recordHash=… at=…</code> (in JSON-Logs ein JSON-Objekt mit diesen Feldern, siehe <a href="#log-format">Log-Format</a>). Bewahre das Backend-Log außerhalb des Datenbank-Hosts auf (Log-Shipper, journald, SIEM): Checkpoints sind nur so vertrauenswürdig wie der Ort, an dem sie liegen. Übergib die Logdatei mit <code>--checkpoints=</code>, um gelöschte neueste Einträge oder ein eingespieltes älteres Backup zu erkennen.</p><h2 id="deactivate-the-local-system-admin-account" tabindex="-1">Lokales Systemadmin-Konto deaktivieren <a class="header-anchor" href="#deactivate-the-local-system-admin-account" aria-label="Permalink to “Lokales Systemadmin-Konto deaktivieren”">​</a></h2><p>Nach der Übergabe der Systemadministration an eine IdP-Gruppe (siehe <a href="./roles-and-permissions#hand-over-system-administration-to-an-idp-group">Rollen und Berechtigungen</a>) deaktivierst du das lokale Konto des Bootstrappings, damit kein zusätzlicher Passwortzugang offen bleibt. Du brauchst die Berechtigung <code>auth-config:manage</code>:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/admin/system-admin-account&quot;</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">                     # Zustand des Kontos</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/admin/system-admin-account/deactivate&quot;</span></span></code></pre></div><ul><li>Die Sitzungen des Kontos enden sofort, und sein Passwort funktioniert nicht mehr; Anmeldungen über den Identity-Provider sind nicht betroffen.</li><li>OEA lehnt die Deaktivierung mit <code>409</code> und dem Problemtyp <code>urn:oea:problem:last-admin-path</code> ab, solange es keinen anderen funktionierenden Weg zur Systemadministration gibt: eine aktive Zuordnung eines aktiven Providers zu <code>system-admin</code>, die die Rolle bei mindestens einer Anmeldung vergeben hat (<code>lastMatchedAt</code>), oder eine <code>system-admin</code>-Zuweisung ohne <code>validTo</code> an eine aktive Person (siehe <a href="./roles-and-permissions#assign-roles-to-a-single-person">Rollen einer einzelnen Person zuweisen</a>). Verlässt du dich auf eine Gruppe, lass kurz vor der Deaktivierung ein Mitglied der Gruppe sich anmelden.</li><li>Die Deaktivierung und ein abgelehnter Versuch stehen im Audit-Trail (<code>system-admin-account.deactivated</code>).</li><li>Dieselbe Prüfung lehnt den Entzug der letzten <code>system-admin</code>-Zuweisung und das Löschen, Deaktivieren oder Umhängen der letzten funktionierenden Zuordnung zu <code>system-admin</code> ab. Sperrst du dich trotzdem aus, etwa weil die Mitglieder der Gruppe sie beim Provider verlassen haben, hilft die Wiederherstellung unten.</li></ul><h2 id="recover-administrator-access" tabindex="-1">Administratorzugang wiederherstellen <a class="header-anchor" href="#recover-administrator-access" aria-label="Permalink to “Administratorzugang wiederherstellen”">​</a></h2><p>Kann niemand mehr die Instanz administrieren – das Passwort des lokalen Kontos ist verloren oder das Konto ist deaktiviert, und keine IdP-Gruppenzuordnung zu <code>system-admin</code> funktioniert –, stellst du das lokale Konto mit einem Befehl im Backend-Container wieder her. Er nutzt die Konfiguration des Containers (Datenbank und Key-Encryption-Key):</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -it</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /app/oea-backend.jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> admin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> recover</span></span></code></pre></div><ol><li>Gib das neue Passwort zweimal ein (12 bis 128 Zeichen). Es wird vom Terminal gelesen und steht nie in der Befehlszeile.</li><li>Ist die Setup-Phase beendet, ersetzt der Befehl auch den zweiten Faktor: Er widerruft den alten Authenticator, zeigt einmal ein neues Geheimnis und eine <code>otpauth</code>-URI und fragt nach einem Code aus deiner Authenticator-App (drei Versuche).</li><li>Das Konto ist wieder aktiv, alle seine Sitzungen sind widerrufen, und seine Anmeldedrosselung ist zurückgesetzt. Melde dich mit dem neuen Passwort und, nach der Setup-Phase, einem Code des neuen Authenticators an.</li></ol><p>Ohne Terminal (<code>docker compose exec -T</code>) liest der Befehl eine Antwort pro Zeile von der Standardeingabe. Exit-Codes: <code>0</code> wiederhergestellt, <code>1</code> abgelehnt (Instanz nicht gebootstrappt, falsche Codes oder Eingabe beendet – nichts wurde geändert), <code>2</code> Aufruf- oder Verbindungsfehler.</p><p>Die Wiederherstellung steht im Audit-Trail als <code>system.admin-recovered</code> mit der Quelle <code>CLI</code>. Weder Passwort noch Geheimnis werden gespeichert oder geloggt. Das Geheimnis bleibt im Verlauf deines Terminals; leere das Terminal danach. Wer Befehle im Backend-Container ausführen kann, kann die Instanz auf diesem Weg übernehmen – das erlauben das Datenbankpasswort und der Schlüssel im selben Container ohnehin. Behandle Zugriff auf den Container wie Administratorzugriff.</p><h2 id="postgresql-auf-eine-neue-hauptversion-aktualisieren" tabindex="-1">PostgreSQL auf eine neue Hauptversion aktualisieren <a class="header-anchor" href="#postgresql-auf-eine-neue-hauptversion-aktualisieren" aria-label="Permalink to “PostgreSQL auf eine neue Hauptversion aktualisieren”">​</a></h2><p>Das Compose-Setup verwendet PostgreSQL 18. Datenverzeichnisse sind zwischen Hauptversionen nicht kompatibel, ein Upgrade der Hauptversion braucht daher Dump und Restore oder <code>pg_upgrade</code>:</p><ol><li>Stoppe das Backend, lass PostgreSQL laufen und erstelle als Superuser einen Dump der Datenbank: <code>pg_dumpall</code> (Rollen und Daten) oder <code>pg_dump -Fc oea</code> plus das Provisioning-Skript für die Rollen.</li><li>Starte die neue PostgreSQL-Version auf einem leeren Volume; das Provisioning-Skript legt die Rollen erneut an.</li><li>Spiel den Dump ein, führe dann den Migrationsschritt aus und starte das Backend.</li></ol><p>Seit PostgreSQL 18 legt das offizielle Image seine Daten in <code>/var/lib/postgresql/18/docker</code> ab; das Compose-Volume ist deshalb unter <code>/var/lib/postgresql</code> eingebunden. Die minimal unterstützte Version bleibt PostgreSQL 15; das Backend prüft sie beim Start.</p>`,49)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};